// Shape and reserved words first - both are free to check and neither
// needs the cluster. If a name fails here there is nothing to look up.
//
// THIS LIST MUST MATCH `Validate input` in the provisioning workflow.
// They are separate copies because the two workflows are separate, and
// wfcheck.js asserts they are identical - a name this check calls free
// but the provisioner then rejects would be the worst of both.
const RESERVED = [
  'default', 'kube-system', 'kube-public', 'kube-node-lease',
  'build', 'registry', 'monitoring', 'signup', 'n8n', 'dex', 'vault',
  'user1', 'user2',
  'www', 'api', 'admin', 'apps', 'auth', 'login', 'portal', 'mail',
  'ns1', 'static', 'cdn', 'root', 'system'
];

// Two triggers, two shapes: a webhook nests the payload under .body,
// the Execute Workflow trigger passes the item as-is. Accept both so
// the rules below never depend on how the question arrived.
const raw = $input.first().json || {};
const inp = raw.body || raw;
const name = String(inp.name || '').trim().toLowerCase();
const username = String(inp.username || '').trim().toLowerCase();

let ok = true, reason = '';
if (!/^[a-z][a-z0-9-]{1,28}[a-z0-9]$/.test(name)) {
  ok = false; reason = 'shape';
} else if (name.indexOf('--') !== -1) {
  ok = false; reason = 'shape';
} else if (RESERVED.indexOf(name) !== -1) {
  ok = false; reason = 'reserved';
} else if (/^(kube-|proj-|tenant-)/.test(name)) {
  ok = false; reason = 'reserved';
}

// The namespace name is the uniqueness key: a tenant's hostname is
// derived from it, so a free namespace means a free name. That is why
// no Ingress listing is needed here - and why n8n needs no extra RBAC.
return [{ json: { name, username, shapeOk: ok, reason,
  namespace: 'tenant-' + name } }];

// One answer, and it never guesses. If a lookup could not be completed
// the name is reported as UNKNOWN rather than free: telling a user a
// name is available and then refusing it at submit time is worse than
// asking them to try again.
const n = $('Is the name usable at all?').first().json;

function seen(nodeName) {
  // true  = the object exists (name taken)
  // false = a clean 404 (name free)
  // null  = we could not tell
  try {
    const j = $(nodeName).first().json;
    if (!j) return null;
    if (j.kind === 'Namespace' && j.metadata) return true;      // k8s hit
    if (j.Name) return true;                                    // nomad hit
    const s = JSON.stringify(j);
    if (s.indexOf('NotFound') !== -1 || s.indexOf('404') !== -1) return false;
    if (s.indexOf('not found') !== -1) return false;
    return null;
  } catch (e) { return null; }
}

let ownedBy = '';
try {
  const k = $('Taken on Kubernetes?').first().json;
  if (k && k.metadata && k.metadata.labels) {
    ownedBy = k.metadata.labels.owner || k.metadata.labels.tenant || '';
  }
} catch (e) { ownedBy = ''; }

const k8s = seen('Taken on Kubernetes?');
const nomad = seen('Taken on Nomad?');

let available = false, reason = n.reason;
if (!n.shapeOk) {
  available = false;                       // reason already set
} else if (k8s === null || nomad === null) {
  available = false; reason = 'unknown';
} else if (k8s || nomad) {
  available = false;
  reason = (ownedBy && ownedBy === n.username) ? 'yours' : 'taken';
} else {
  available = true; reason = 'free';
}

return [{ json: { name: n.name, available, reason,
  ownedByYou: reason === 'yours', namespace: n.namespace } }];
